INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (112611, 7, "もうっ、キャルキャル～\nあんま言わないでよ～！\n私たちだってわかってるんだからさ～", "", 1, 1070036, 1, 11, "", "", 10);
